window.RP_SESSION={"id":"S-ef9cf096f0ce","messages":[{"id":"RP-III-0119640","time":"2026-07-08T22:30:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아도니스는 오늘이 생에 첫 장례식이었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119641","time":"2026-07-08T22:31:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사실, 그가 장례식에 참석한 것은 오늘이 처음이 아니었다. 그의 부모의 장례에도 그가 있었으니까.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119642","time":"2026-07-08T22:32:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"하지만 아도니스는 아직 그와 자신의 연속성을 뚜렷히 느끼지 못하고 있으니, 편의상 처음이라고 말해보자.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119643","time":"2026-07-08T22:33:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119644","time":"2026-07-08T22:34:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 장례식 내내, 하고 싶은 질문이 많았다. 왜 망자에게 꽃을 주는 건지, 왜 이런 것을 하는건지. 그래도 꾸욱꾸욱 참았다.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119645","time":"2026-07-08T22:37:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아도니스는 의뢰 중 사람을 마구 괴롭히는 악당을 만난 적이 있었다. 몇 주 전의 일이었다. 아도니스도 슬펐고, 동료들도 당연하다는 듯이 그에게 분노했다. 사람을 자기 만족을 위한 도구로 보는 것은 큰 죄라고 했다.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119646","time":"2026-07-08T22:39:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아도니스는 그것을 충분히 이해했다.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119647","time":"2026-07-08T22:40:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 고기를 위해 동물들을 좁은 공간에 평생 가둬두고 번식시키거나, 땅을 파고 식물을 꺾어 염색시키지 않아도 되는 옷을 물들이거나...","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119648","time":"2026-07-08T22:41:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"음. 그럴수있지. 욕망을 하고, 실현시키는 건 문제 되지 않는다.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119649","time":"2026-07-08T22:42:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"하고 싶고 할 수 있는데 안 할 이유가 어디있는가","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119650","time":"2026-07-08T22:43:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"다만 사람들은 자기 종족에 대한 애착이 다른 친구들에 비해 엄-청 강하구나.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119651","time":"2026-07-08T22:43:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"나도 그런가? 하는, 좋은 생각의 기회가 되었을 뿐이었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119652","time":"2026-07-08T22:43:00+09:00","room":"RP III","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6eeed2b4661f"]},{"id":"RP-III-0119653","time":"2026-07-08T22:43:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
